// Relocation Context Simulation
typedef unsigned int uint32_t;
typedef short uint16_t;

// Program image offset assumptions (from linker)
const uint32_t LINK_BASE = 0x100000;

// Actual load location (at runtime)
uint32_t actual_LOAD_ADDR = 0xA00000;

// Simulated Program Memory (e.g., instruction data)
uint32_t program_mem[512];

// Relocation Table Entry: Offset to patch (e.g., 4th word)
uint16_t patch_index = 4;

// Stored address/offset requiring adjustment
uint32_t original_val = program_mem[patch_index];

// Calculate load delta
int32_t delta = actual_LOAD_ADDR - LINK_BASE;

// Address Patching (Absolute Relocation Type)
program_mem[patch_index] = original_val + delta;
// Reference is now correctly patched to actual memory location.
